import { dashboardSessionUrl } from "../../dashboard-session-url.js";
import { markdownToSlackMrkdwn, updateMessage } from "./api.js";
export function turnDurationMs(startedAtMs) {
    if (startedAtMs === null || startedAtMs === undefined) {
        return 0;
    }
    return Math.max(0, Date.now() - startedAtMs);
}
export function formatElapsed(ms) {
    if (ms < 10_000) {
        return `${(ms / 1000).toFixed(1)}s`;
    }
    const total = Math.round(ms / 1000);
    const h = Math.floor(total / 3600);
    const m = Math.floor((total % 3600) / 60);
    const s = total % 60;
    if (h > 0) {
        return `${h}h ${m}m ${s}s`;
    }
    if (m > 0) {
        return `${m}m ${s}s`;
    }
    return `${s}s`;
}
export async function resolveSlackFooterBlocks(footer, ctx) {
    if (footer === undefined) {
        return undefined;
    }
    const text = typeof footer === "function" ? await footer(ctx) : footer;
    if (text === undefined || text.trim() === "") {
        return undefined;
    }
    return [
        {
            type: "context",
            elements: [{ type: "mrkdwn", text }],
        },
    ];
}
export function slackPostedReply(args) {
    const text = markdownToSlackMrkdwn(args.text);
    if (args.footer === undefined || args.footer.length === 0) {
        return { text, blocks: undefined };
    }
    return {
        text,
        blocks: [{ type: "section", text: { type: "mrkdwn", text } }, ...args.footer],
    };
}
export async function paintSlackFooter(args) {
    const blocks = await resolveSlackFooterBlocks(args.footer, args.ctx);
    if (blocks === undefined) {
        return undefined;
    }
    const body = slackPostedReply({ text: args.ctx.text, footer: blocks });
    return updateMessage({
        botToken: args.botToken,
        channel: args.ctx.channelId,
        ts: args.ts,
        text: body.text,
        blocks: body.blocks,
    });
}
export function slackSessionFooter(opts) {
    return (ctx) => {
        const url = dashboardSessionUrl(ctx.sessionId, { slug: opts?.slug });
        if (url === undefined) {
            return undefined;
        }
        return `<${url}|View session> · ${formatElapsed(ctx.durationMs)}`;
    };
}
